mapper.select:
SELECT id, user_id, title, description, category_id, price, original_price, images, cover_image, `condition`, trade_type, `status`, view_count, like_count, favorite_count, latitude, longitude, location, create_time, update_time, deleted FROM item
deleted = 0 AND user_id = #{userId}
AND `status` = #{status}
ORDER BY create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM item

    deleted = 0
    AND user_id = #{userId}

        AND `status` = #{status}

SELECT DISTINCT item.id, item.user_id, item.title, item.description, item.category_id, item.price, item.original_price, item.images, item.cover_image, item.`condition`, item.trade_type, item.`status`, item.view_count, item.like_count, item.favorite_count, item.latitude, item.longitude, item.location, item.create_time, item.update_time, item.deleted
FROM item item LEFT JOIN user u ON item.user_id = u.id LEFT JOIN user_credit uc ON u.id = uc.user_id
item.deleted = 0
AND item.`status` = #{query.status}
AND item.`status` = 1
AND item.category_id = #{query.categoryId}
AND (item.title LIKE CONCAT('%', #{query.keyword}, '%') OR item.description LIKE CONCAT('%', #{query.keyword}, '%'))
AND item.geohash LIKE CONCAT(LEFT(ST_GEOHASH(POINT(#{query.userLongitude}, #{query.userLatitude}), 6), 4), '%') AND MBRContains( ST_Buffer( POINT(#{query.userLongitude}, #{query.userLatitude}), #{query.distance} / 111.0 ), item.location_point ) AND ST_DISTANCE_SPHERE( POINT(#{query.userLongitude}, #{query.userLatitude}), item.location_point ) / 1000.0 <= #{query.distance}
AND item.`condition` IN
#{cond}
AND item.trade_type = #{query.tradeType}
AND item.price >= #{query.minPrice}
AND item.price <= #{query.maxPrice}
ORDER BY distance ASC, item.create_time DESC
ORDER BY item.create_time DESC
ORDER BY item.like_count DESC, item.view_count DESC, item.create_time DESC
ORDER BY match_score DESC, item.create_time DESC

SELECT DISTINCT item.id, item.user_id, item.title, item.description, item.category_id, item.price, item.original_price, item.images, item.cover_image, item.`condition`, item.trade_type, item.`status`, item.view_count, item.like_count, item.favorite_count, item.latitude, item.longitude, item.location, item.create_time, item.update_time, item.deleted, ( CASE WHEN item.category_id = #{categoryId} THEN 50 ELSE 0 END + CASE WHEN #{keyword} IS NOT NULL AND #{keyword} != '' AND (item.title LIKE CONCAT('%', #{keyword}, '%') OR item.description LIKE CONCAT('%', #{keyword}, '%')) THEN 30 ELSE 0 END + CASE WHEN #{minPrice} IS NOT NULL AND #{maxPrice} IS NOT NULL AND item.price >= #{minPrice} AND item.price <= #{maxPrice} THEN 20 ELSE 0 END + (COALESCE(item.view_count, 0) / 1000.0) * 5 + (COALESCE(item.like_count, 0) / 100.0) * 5 + (1 - DATEDIFF(NOW(), item.create_time) / 30.0) * 10 ) AS match_score FROM item item
item.deleted = 0 AND item.`status` = 1 AND item.id != #{itemId}
AND item.category_id = #{categoryId}
AND item.price >= #{minPrice} AND item.price <= #{maxPrice}
ORDER BY match_score DESC, item.create_time DESC LIMIT #{limit}
